select id, product_name, brand, stock_qty, tags, supplier_id, avg(cost) over (partition by supplier_id order by cost, id rows between 2 preceding and 1 preceding) cost_avg_2_prior, last_value(brand, true) over (partition by brand order by launch_date, id rows between unbounded preceding and current row) last_known_brand, first_value(brand) ignore nulls over (order by cost, id rows between unbounded preceding and current row) first_known_brand from products
